// Class 12 Business Studies practice bank, part 2: Directing, Controlling, Financial Management, Financial Markets, Marketing, Consumer Protection.
StudyData.addPractice(12, "business", {
  "directing": {
    mcq: [
      { q: "Which of the following is NOT an element of directing?", options: ["Supervision", "Motivation", "Staffing", "Communication"], answer: 2, explain: "The four elements of directing are supervision, motivation, leadership and communication. Staffing is a separate function of management.", level: 1 },
      { q: "Which need is at the top of Maslow's need hierarchy?", options: ["Esteem need", "Safety need", "Physiological need", "Self-actualisation need"], answer: 3, explain: "Self-actualisation, the urge to become what one is capable of becoming, is the highest need in Maslow's hierarchy.", level: 1 },
      { q: "The informal network of communication that arises from social interaction among employees is called the:", options: ["Grapevine", "Wheel", "Inverted V", "Single chain"], answer: 0, explain: "The grapevine is informal communication. Wheel, inverted V and single chain are formal networks.", level: 1 },
      { q: "Directing is a function that flows:", options: ["from bottom to top", "from top to bottom", "only between people at the same level", "from outside the organisation inwards"], answer: 1, explain: "Directing starts at the top level, where managers instruct, and flows downwards through every level.", level: 1 },
      { q: "Which of the following is a financial incentive?", options: ["Status", "Job enrichment", "Profit sharing", "Employee empowerment"], answer: 2, explain: "Profit sharing gives employees a share in profits. Status, job enrichment and empowerment are non-financial incentives.", level: 1 },

      { q: "Rangoli Textiles allows its long-serving staff to buy the company's shares at a price lower than the market price so that they become part-owners. This incentive is:", options: ["Job enrichment", "Co-partnership or stock option", "A perquisite", "Employee recognition"], answer: 1, explain: "Offering shares to employees at a price below the market price is a co-partnership/stock option scheme, a financial incentive.", level: 2 },
      { q: "In the wheel network of formal communication:", options: ["everyone communicates freely with everyone", "messages pass in a circle between neighbours", "all subordinates communicate through a common superior", "messages flow down a single line only"], answer: 2, explain: "In the wheel, subordinates are not connected to each other. They all communicate through one superior at the centre.", level: 2 },
      {
        q: "Assertion (A): Autocratic leadership may be suitable when quick decisions are needed.\nReason (R): In the autocratic style, decisions are centralised in the leader, who gives orders and expects obedience.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Because the leader alone decides and does not consult subordinates, time is saved, so the style suits situations that need quick decisions.", level: 2, keepOrder: true
      },
      { q: "Sunita, head of design at Sapna Studios, lets her designers choose their own projects and methods and steps in only when they ask for help. Her style of leadership is:", options: ["Autocratic", "Democratic", "Laissez-faire", "Supervision without leadership"], answer: 2, explain: "Sunita gives a high degree of independence to subordinates and acts as a supporter. This is laissez-faire (free-rein) leadership.", level: 2 },
      { q: "A bank circular was written in complicated legal language and badly translated into Punjabi, so branch staff misunderstood the new rule. Which barrier to communication is this?", options: ["Semantic barrier", "Psychological barrier", "Organisational barrier", "Personal barrier"], answer: 0, explain: "Badly expressed messages, difficult language and faulty translation are semantic barriers.", level: 2 },

      { q: "Gurpreet has a permanent job and good friends at work. His manager gives him an 'Employee of the Month' award with a public announcement. Which need of Maslow's hierarchy is mainly being met?", options: ["Affiliation need", "Esteem need", "Self-actualisation need", "Safety need"], answer: 1, explain: "Recognition, status and public praise satisfy esteem needs. His safety and affiliation needs are already met.", level: 3 },
      {
        q: "Assertion (A): Money is the only motivator for employees.\nReason (R): Non-financial incentives such as recognition and job enrichment can satisfy higher-order needs like esteem and self-actualisation.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "A is false, since non-financial incentives also motivate people. R is true and shows why money alone is not enough.", level: 3, keepOrder: true
      },
      { q: "Which pair of barrier and its type is correctly matched?", options: ["Technical jargon: psychological barrier", "Fear of challenge to authority: organisational barrier", "Premature evaluation: psychological barrier", "Complex organisation structure: personal barrier"], answer: 2, explain: "Premature evaluation is psychological. Technical jargon is semantic, fear of challenge to authority is personal and a complex structure is organisational.", level: 3 },
      { q: "Which is the correct order of needs in Maslow's hierarchy, from lowest to highest?", options: ["Physiological, Affiliation, Safety, Esteem, Self-actualisation", "Safety, Physiological, Affiliation, Esteem, Self-actualisation", "Physiological, Safety, Esteem, Affiliation, Self-actualisation", "Physiological, Safety, Affiliation, Esteem, Self-actualisation"], answer: 3, explain: "The order is physiological, safety/security, affiliation/belonging, esteem and self-actualisation.", level: 3 }
    ],
    written: [
      { q: "Name the four elements of directing.", a: "The four elements of directing are supervision, motivation, leadership and communication.", marks: 1 },
      { q: "What is meant by grapevine communication?", a: "Grapevine is the informal communication network that arises from social interaction among employees. It spreads fast but may distort facts.", marks: 1 },
      { q: "State any two features of directing.", a: "1. Directing initiates action: work begins when instructions are given.\n2. Directing takes place at every level of management and is a continuous process. (Also: it flows from top to bottom.)", marks: 2 },
      { q: "Distinguish between autocratic and democratic leadership on any two points.", a: "1. Decision-making: the autocratic leader decides alone; the democratic leader decides after consulting subordinates.\n2. Communication: it is one-way (orders) in the autocratic style and two-way in the democratic style, where subordinates are encouraged to participate.", marks: 2 },
      { q: "Explain any three financial incentives.", a: "1. Bonus: a payment over and above salary, given to employees for good work or on special occasions.\n2. Profit sharing: employees are given a share in the profits of the firm, which makes them work for its success.\n3. Co-partnership/stock option: employees are offered shares at a price lower than the market price, so they feel like owners. (Others: productivity-linked wage incentives, retirement benefits, perquisites.)", marks: 3 },
      { q: "Explain any three organisational or personal barriers to communication.", a: "1. Organisational policy: a rigid policy that discourages free flow of information hinders communication.\n2. Status: differences in rank make subordinates hesitate to speak freely to superiors.\n3. Fear of challenge to authority (personal barrier): a superior may avoid sharing information, fearing it will weaken his authority. (Also: complex structure, unwillingness to communicate.)", marks: 3 },
      { q: "Explain the importance of directing with any three points.", a: "1. It initiates action: it is the starting point of work, as employees begin work only after getting directions.\n2. It integrates employees' efforts so that they work towards common organisational goals.\n3. It motivates employees and helps them to adapt to change, and brings stability and balance in the organisation.", marks: 3 },
      { q: "Explain Maslow's need hierarchy theory of motivation. State its assumptions and give an example of a workplace incentive for each need.", a: "Maslow's hierarchy has five levels of need, from lowest to highest:\n1. Physiological needs: food, clothing and shelter. Workplace: basic salary.\n2. Safety/security needs: physical and economic security. Workplace: job security, pension.\n3. Affiliation/belonging needs: acceptance and friendship. Workplace: a friendly work group.\n4. Esteem needs: self-respect, status, recognition. Workplace: promotion, awards.\n5. Self-actualisation needs: becoming what one is capable of becoming. Workplace: challenging work and growth opportunities.\nAssumptions: behaviour depends on needs; needs are arranged in a hierarchy; a satisfied need no longer motivates; a person moves to the next level only when the lower need is satisfied.", marks: 5 },
      { q: "Explain the elements of the communication process.", a: "1. Sender: the person who conveys the message.\n2. Message: the idea, feeling or information to be communicated.\n3. Encoding: converting the message into symbols such as words, pictures or gestures.\n4. Media: the path through which the encoded message is sent, e.g. a letter, phone call or e-mail.\n5. Decoding: the receiver converts the symbols back into meaning.\n6. Receiver: the person to whom the message is sent.\n7. Feedback: the receiver's response, showing whether the message was understood.\n8. Noise: any disturbance that hinders communication at any stage.", marks: 5 },
      { q: "Case study: Jaswant Singh manages the dispatch section of Kisan Foods. He gives orders and expects workers to obey without question. Workers have stopped giving suggestions, and one worker said, 'I am scared to tell him about the faulty packing machine.' Jaswant also announces the new shift schedule in English technical terms, which many workers cannot follow. Yet the workers have a stable income and good friendships and now want recognition.\n(i) Identify the leadership style of Jaswant.\n(ii) Name the barriers to communication, quoting from the case.\n(iii) Which need of Maslow's hierarchy do the workers now have? Suggest one incentive.", a: "(i) Autocratic leadership, because he 'gives orders and expects workers to obey without question' and workers have stopped giving suggestions, showing one-way communication.\n(ii) Psychological/personal barrier: 'scared to tell him about the faulty packing machine' shows fear and distrust of the superior, so information is not passed upward. Semantic barrier: announcing the schedule in 'English technical terms' that workers cannot follow is technical jargon.\n(iii) Esteem needs, because their physiological, safety and affiliation needs ('stable income and good friendships') are already satisfied and they 'want recognition'. A suitable incentive is an employee recognition programme or a promotion.", marks: 4, type: "case" }
    ]
  },
  "controlling": {
    mcq: [
      { q: "The first step in the controlling process is:", options: ["Analysing deviations", "Setting performance standards", "Measuring actual performance", "Taking corrective action"], answer: 1, explain: "Standards must exist before performance can be measured and compared, so setting standards comes first.", level: 1 },
      { q: "In the controlling process, a 'deviation' means:", options: ["the planned target itself", "the total output of the firm", "the amount of budget left unspent", "the difference between actual performance and the standard"], answer: 3, explain: "Deviation is the gap between actual performance and the standard. Comparing the two reveals it.", level: 1 },
      { q: "KRAs, the focus of critical point control, stand for:", options: ["Key Result Areas", "Key Resource Allocations", "Keen Review Activities", "Known Risk Areas"], answer: 0, explain: "Key Result Areas are the areas critical to the success of the organisation, where deviations need immediate attention.", level: 1 },
      { q: "Which of the following is a limitation of controlling?", options: ["Ensuring order and discipline", "Improving employee motivation", "It is a costly affair", "Judging the accuracy of standards"], answer: 2, explain: "Controlling needs heavy spending of time, effort and money, so it is costly. The other options are its importance.", level: 1 },
      { q: "Planning is prescriptive, whereas controlling is:", options: ["creative", "evaluative", "directive", "advisory"], answer: 1, explain: "Planning says what should be done; controlling evaluates whether it was done as planned.", level: 1 },

      { q: "Which of the following is a way of measuring actual performance?", options: ["Sample checking", "Setting Key Result Areas", "Management by exception", "Revising the standards"], answer: 0, explain: "Actual performance is measured by personal observation, sample checking and performance reports.", level: 2 },
      { q: "If a deviation is found to be due to unrealistic standards, the manager should:", options: ["retrain the workers", "replace the machinery", "introduce new incentive plans", "revise the standards"], answer: 3, explain: "When standards themselves are faulty, corrective action means revising them rather than changing inputs or people.", level: 2 },
      {
        q: "Assertion (A): Controlling is both a forward-looking and a backward-looking function.\nReason (R): Plans are based on past experience, and the results of control are used to improve future plans.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Control looks back at performance, but it also feeds lessons into future plans. R explains A.", level: 2, keepOrder: true
      },
      { q: "At Spice Route restaurants, head office receives a report from an outlet only when its food cost goes above the permitted 35% of sales. This is an application of:", options: ["Critical point control", "Standardisation", "Management by exception", "Corrective action"], answer: 2, explain: "Only significant deviations beyond the permissible limit (35%) are reported to top management: management by exception.", level: 2 },
      { q: "A cement company's costs rose after the government increased the tax on fuel. The company could not prevent this. Which limitation of controlling is shown?", options: ["Costly affair", "Little control on external factors", "Resistance from employees", "Difficulty in setting quantitative standards"], answer: 1, explain: "Government policy is an external factor that a firm cannot control.", level: 2 },

      { q: "A call-centre finds that customer complaints are rising because new agents lack product knowledge. The most suitable corrective action is to:", options: ["change the quality specifications of materials", "upgrade the technology", "modify the existing process", "modify the training programme"], answer: 3, explain: "Ineffective training is corrected by modifying the training programmes.", level: 3 },
      {
        q: "Assertion (A): Controlling has no use if planning has not been done.\nReason (R): Controlling is a backward-looking function only.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 2, explain: "A is true, since plans give the standards to compare with. R is false, because controlling is also forward-looking.", level: 3, keepOrder: true
      },
      { q: "A firm allows labour cost to rise by at most 5%. The increases in three plants are: Plant A 4%, Plant B 6%, Plant C 8%. Under management by exception, which plants are reported to top management?", options: ["Only Plant C", "Plants A and B", "Plants B and C", "All three plants"], answer: 2, explain: "Only deviations beyond the permissible 5% are reported: B (6%) and C (8%). Plant A is within limit.", level: 3 },
      { q: "Which statement about planning and controlling is correct?", options: ["Planning is evaluative and controlling is prescriptive", "Planning without controlling is meaningless, and controlling without planning is blind", "Controlling can work even if no standards are set", "Planning is needed only at the top level while controlling is needed only at the lower level"], answer: 1, explain: "They are inseparable twins. Planning gives the standards, and controlling checks performance against them.", level: 3 }
    ],
    written: [
      { q: "Define controlling.", a: "Controlling means ensuring that activities in an organisation are performed according to plans, and that resources are used effectively and efficiently.", marks: 1 },
      { q: "What are Key Result Areas?", a: "Key Result Areas (KRAs) are the areas of activity that are critical to the success of the organisation. Control is focused on them (critical point control).", marks: 1 },
      { q: "State any two limitations of controlling.", a: "1. Difficulty in setting quantitative standards: morale and job satisfaction cannot be easily measured.\n2. Little control on external factors such as government policy, technology and competition. (Also: resistance from employees; costly affair.)", marks: 2 },
      { q: "Why is controlling called a goal-oriented function? Give any two points of its importance.", a: "Controlling ensures that activities move according to plans so that organisational goals are reached; hence it is goal-oriented.\n1. It helps accomplish organisational goals by pointing out deviations.\n2. It helps in judging the accuracy of standards and in making efficient use of resources. (Also: improves motivation, ensures order and discipline, facilitates coordination.)", marks: 2 },
      { q: "Distinguish between planning and controlling on any three points.", a: "1. Nature: planning is prescriptive (it says what should be done); controlling is evaluative (it checks what was done).\n2. Basis: planning sets the standards; controlling measures performance against those standards.\n3. Time view: planning is said to look ahead and controlling to look back, but both are forward- and backward-looking, because plans use past experience and control results improve future plans.", marks: 3 },
      { q: "Explain 'management by exception' with an example. State any two benefits.", a: "1. Meaning: only significant deviations beyond the permissible limit are brought to the notice of top management, since an attempt to control everything results in controlling nothing.\n2. Example: if a plan allows labour cost to rise by up to 2%, only a rise beyond 2% is reported.\n3. Benefits: it saves managers' time and effort, and it focuses attention on important problems while lower levels handle routine matters.", marks: 3 },
      { q: "A plant's standard is 1,000 units a day with a permitted shortfall of 5%. Last week's actual output was 900 units a day. (a) Calculate the deviation in percentage. (b) Should it be reported to top management? Name the controlling step involved and give one possible corrective action.", a: "1. Deviation = 1,000 − 900 = 100 units, i.e. 100 ÷ 1,000 × 100 = 10%.\n2. This exceeds the permissible 5%, so under management by exception it should be reported. The step involved is analysing deviations.\n3. Corrective action, depending on the cause found: e.g. repair or replace defective machinery, or modify the training programme.", marks: 3 },
      { q: "Explain the steps in the controlling process.", a: "1. Setting performance standards: benchmarks, quantitative (output, cost, revenue) or qualitative, against which performance is measured; they should be flexible.\n2. Measurement of actual performance: through personal observation, sample checking and performance reports; it should be objective.\n3. Comparing actual performance with standards: this shows the deviation.\n4. Analysing deviations: the causes and importance of deviations are studied, using critical point control and management by exception.\n5. Taking corrective action: if deviations exceed acceptable limits, steps are taken to prevent their recurrence; if standards were unrealistic, they are revised.", marks: 5 },
      { q: "Explain the importance of controlling.", a: "1. Accomplishing organisational goals: it points out deviations from plans so that corrective action can be taken.\n2. Judging the accuracy of standards: by checking, it shows whether standards are right or need revision.\n3. Making efficient use of resources: each activity is performed according to standards, so waste is reduced.\n4. Improving employee motivation: employees who know their standards work with more effort when performance is judged on them.\n5. Ensuring order and discipline: it creates an atmosphere of discipline and reduces dishonest behaviour.\n6. Facilitating coordination in action: activities of all departments are linked to the same standards.", marks: 5 },
      { q: "Case study: Annapurna Bakery has set a standard that not more than 2% of its daily output of 5,000 loaves may be rejected. In the last month, rejection rose to 6%. Investigation showed that the old oven in the baking section was heating unevenly. The owner also found that the cost of packing paper rose by 3%, but he decided not to worry about it, as bread flour and oven fuel are the major cost items.\n(i) Identify the steps of the controlling process shown in the case.\n(ii) Suggest the corrective action.\n(iii) Which concept of controlling does the owner's decision about packing paper show?", a: "(i) Setting standards ('not more than 2% ... rejected'), measuring actual performance (rejection of 6%), comparing and analysing deviations (a 4% deviation traced to 'the old oven ... heating unevenly').\n(ii) The machinery is defective or obsolete, so it should be repaired or replaced, i.e. technological upgradation.\n(iii) Critical point control: the owner focuses on Key Result Areas such as flour and fuel costs, and does not worry about the minor packing paper cost.", marks: 4, type: "case" }
    ]
  },
  "financial-management": {
    mcq: [
      { q: "The primary objective of financial management is:", options: ["maximising sales in the current year", "wealth maximisation, i.e. maximising the market value of equity shares", "minimising the tax paid by the firm", "maximising the number of shareholders"], answer: 1, explain: "Wealth maximisation means increasing the market price of the company's shares, which is the shareholders' wealth.", level: 1 },
      { q: "Long-term investment decisions, such as buying new machinery or setting up a plant, are known as:", options: ["dividend decisions", "working capital decisions", "financing decisions", "capital budgeting decisions"], answer: 3, explain: "Capital budgeting decisions are long-term investment decisions. Working capital decisions are short-term investment decisions.", level: 1 },
      { q: "Net working capital is equal to:", options: ["current assets minus current liabilities", "fixed assets minus current assets", "total assets minus owners' funds", "current assets plus current liabilities"], answer: 0, explain: "Net working capital = current assets − current liabilities. Gross working capital is the total of current assets.", level: 1 },
      { q: "Financial leverage refers to:", options: ["the speed at which a firm pays off its loans", "the ratio of fixed assets to current assets", "the proportion of debt in the total capital of a firm", "the amount of dividend paid per share"], answer: 2, explain: "Financial leverage is the proportion of debt in the capital structure, measured for example by the debt–equity ratio.", level: 1 },
      { q: "Which of the following is a factor affecting the dividend decision?", options: ["Cost of debt", "Growth opportunities", "Floatation costs", "Fixed operating costs"], answer: 1, explain: "Growth opportunities affect how much profit is retained. Cost of debt, floatation costs and fixed operating costs affect the financing decision.", level: 1 },

      { q: "A firm earns a return on investment of 12% but has borrowed at 15% interest. If it raises more debt, its earnings per share are likely to:", options: ["increase", "remain unchanged", "decrease", "double"], answer: 2, explain: "Trading on equity helps only when ROI is higher than the rate of interest. Here ROI < interest, so more debt lowers EPS.", level: 2 },
      { q: "Which firm will need a larger amount of working capital, other things being equal?", options: ["One that allows a long credit period to its customers", "One that gets a long credit period from its suppliers", "One that sells its goods only for cash", "One with a very short production cycle"], answer: 0, explain: "The more credit a firm allows, the more money is locked in debtors, so it needs more working capital. Credit availed has the opposite effect.", level: 2 },
      { q: "The board of Hari Auto is deciding whether to buy a robotic assembly line costing ₹25 crore or to spend the money on enlarging its showroom. This is a:", options: ["financing decision", "dividend decision", "investment (capital budgeting) decision", "working capital decision"], answer: 2, explain: "Choosing which long-term asset to buy is an investment decision, in particular capital budgeting.", level: 2 },
      {
        q: "Assertion (A): A firm with high growth opportunities generally retains more profit and pays a lower dividend.\nReason (R): Shareholders' preference for stable dividends is also considered while taking the dividend decision.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 1, explain: "Both statements are true, but the reason for low dividends in a growing firm is the need for funds for expansion, not shareholder preference.", level: 2, keepOrder: true
      },
      { q: "Shalini Exports earned a record profit this year but declared no dividend, keeping the profit to finance a new factory. Which factor affecting the dividend decision does this show?", options: ["Taxation policy", "Stability of earnings", "Stock market reaction", "Growth opportunities"], answer: 3, explain: "A firm with plans for expansion keeps profits for investment. This is the growth opportunities factor.", level: 2 },

      { q: "A firm has EBIT of ₹12 lakh and pays interest of ₹3 lakh. Its interest coverage ratio is:", options: ["9 times", "0.25 times", "4 times", "3 times"], answer: 2, explain: "ICR = EBIT ÷ Interest = 12 ÷ 3 = 4 times. A higher ratio means the firm can safely use more debt.", level: 3 },
      {
        q: "Assertion (A): A company should use the maximum possible debt whenever it earns a profit.\nReason (R): Debt carries compulsory interest and repayment, which increases the financial risk of the firm.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "A is false, because excess debt raises financial risk. R is true and is the reason the optimal mix of debt and equity must be chosen.", level: 3, keepOrder: true
      },
      { q: "A company has EBIT of ₹6,00,000, pays interest of ₹1,00,000, and tax at 30%. It has 50,000 equity shares. Its earnings per share is:", options: ["₹12", "₹7", "₹10", "₹8.40"], answer: 1, explain: "EBT = 6,00,000 − 1,00,000 = 5,00,000; tax = 1,50,000; EAT = 3,50,000. EPS = 3,50,000 ÷ 50,000 = ₹7.", level: 3 },
      { q: "A firm has fixed assets of ₹20 lakh, current assets of ₹9 lakh and current liabilities of ₹4 lakh. Its net working capital is:", options: ["₹13 lakh", "₹29 lakh", "₹16 lakh", "₹5 lakh"], answer: 3, explain: "Net working capital = current assets − current liabilities = 9 − 4 = ₹5 lakh. Fixed assets are not part of it.", level: 3 }
    ],
    written: [
      { q: "State the primary objective of financial management.", a: "The primary objective is wealth maximisation, i.e. maximising the market value of the company's equity shares.", marks: 1 },
      { q: "What is meant by trading on equity?", a: "Trading on equity means using fixed-cost funds such as debt to increase the earnings per share of equity shareholders. It is favourable only when ROI is higher than the rate of interest.", marks: 1 },
      { q: "Distinguish between gross working capital and net working capital.", a: "1. Gross working capital is the total of current assets of the firm.\n2. Net working capital is current assets minus current liabilities.", marks: 2 },
      { q: "State any two factors that affect the financing decision.", a: "1. Cost: the cost of raising funds from each source (debt is generally cheaper than equity).\n2. Risk: debt carries compulsory interest and repayment, so it raises financial risk. (Also: floatation costs, cash flow position, control considerations, state of capital market.)", marks: 2 },
      { q: "Explain the three financial decisions taken by a finance manager.", a: "1. Investment decision: deciding how the firm's funds should be invested in different assets. Long-term ones are capital budgeting decisions and short-term ones are working capital decisions.\n2. Financing decision: deciding how much finance to raise from long-term sources and in what mix of debt and equity.\n3. Dividend decision: deciding how much of the profit to distribute as dividend and how much to retain for growth.", marks: 3 },
      { q: "Explain any three factors affecting the working capital requirements of a firm.", a: "1. Nature of business: a trading firm needs more current assets (stock) than a service business, so it needs more working capital.\n2. Credit allowed: if more credit is given to customers, more funds are locked in debtors, so more working capital is needed.\n3. Business cycle: in a boom, sales and stocks rise, so more working capital is needed. (Also: scale of operations, production cycle, seasonal factors, inflation.)", marks: 3 },
      { q: "Karan Ltd needs ₹20,00,000 and expects EBIT of ₹4,00,000 (ROI 20%). Plan A: all equity, 2,00,000 shares of ₹10. Plan B: ₹8,00,000 debt at 10% interest and the rest equity (1,20,000 shares of ₹10). The tax rate is 30%. Compare the EPS and say whether trading on equity is favourable.", a: "Plan A: EBIT ₹4,00,000; interest nil; EBT ₹4,00,000; tax 30% = ₹1,20,000; EAT = ₹2,80,000. EPS = 2,80,000 ÷ 2,00,000 = ₹1.40.\nPlan B: interest = 10% of 8,00,000 = ₹80,000; EBT = ₹3,20,000; tax 30% = ₹96,000; EAT = ₹2,24,000. EPS = 2,24,000 ÷ 1,20,000 = ₹1.87 (approx.).\nEPS rises under Plan B because ROI (20%) is higher than the rate of interest (10%). Trading on equity is favourable.", marks: 3 },
      { q: "Explain any five factors that affect the capital structure of a company.", a: "1. Cash flow position: steady and sufficient cash flows allow the firm to use more debt safely.\n2. Interest Coverage Ratio (ICR): the higher the ratio, the lower the risk of default, so more debt can be used.\n3. Debt Service Coverage Ratio (DSCR): a higher ratio means the firm can service more debt.\n4. Return on investment: if ROI is higher than the cost of debt, debt can raise EPS (trading on equity).\n5. Cost of debt and tax rate: debt is cheaper where interest is low and the tax rate high, as interest is tax-deductible.\n6. Control: debt does not dilute the control of existing shareholders, while issuing equity does.\n7. Stock market conditions: in a boom, equity can be issued easily; in a slump, firms prefer debt.", marks: 5 },
      { q: "Explain any five factors affecting the fixed capital requirements of a business.", a: "1. Nature of business: a manufacturing firm needs more fixed capital than a trading firm.\n2. Scale of operations: a large firm needs more fixed assets, hence more fixed capital.\n3. Choice of technique: a capital-intensive firm needs more fixed capital than a labour-intensive one.\n4. Technology upgradation: where technology changes fast, assets become obsolete early and need replacing, so more funds are needed.\n5. Growth prospects: a firm expecting to grow needs higher fixed assets in advance.\n6. Financing alternatives: if assets are taken on lease, less fixed capital is needed.\n(Also: diversification and level of collaboration.)", marks: 5 },
      { q: "Case study: Ishaan Electronics wants to raise ₹10 crore for a new plant. Its earnings are steady and its ROI is 18%, while banks offer loans at 11%. The promoters do not want to share control with new shareholders. Floatation costs of a public equity issue are high. Meanwhile, the firm is also deciding what part of this year's profit to pay as dividend and what part to keep.\n(i) Identify the financial decisions mentioned.\n(ii) Name the factors that favour a higher use of debt, quoting from the case.\n(iii) Which concept is favourable here?", a: "(i) Financing decision (how to raise ₹10 crore) and dividend decision (what part of profit to pay as dividend and what to retain). Setting up the plant is an investment decision.\n(ii) Factors favouring debt: steady earnings ('earnings are steady') which means stable cash flows; ROI higher than the cost of debt ('ROI is 18%, ... loans at 11%'); control ('promoters do not want to share control'); and floatation cost ('floatation costs of a public equity issue are high').\n(iii) Trading on equity, because ROI (18%) is higher than the interest rate (11%), so EPS will rise.", marks: 4, type: "case" }
    ]
  },
  "financial-markets": {
    mcq: [
      { q: "The money market deals in funds with a maturity of up to:", options: ["one month", "six months", "one year", "three years"], answer: 2, explain: "The money market is the market for short-term funds, with maturity up to one year. The capital market deals in medium- and long-term funds.", level: 1 },
      { q: "An unsecured, negotiable promissory note issued by large creditworthy companies to raise short-term funds is called:", options: ["Commercial paper", "Treasury bill", "Debenture", "Equity share"], answer: 0, explain: "Commercial paper is an unsecured promissory note issued for 15 days to one year, often used for bridge financing.", level: 1 },
      { q: "The two depositories in India are:", options: ["BSE and NSE", "SEBI and RBI", "NSE and CDSL", "NSDL and CDSL"], answer: 3, explain: "NSDL (National Securities Depository Ltd) and CDSL (Central Depository Services Ltd) hold securities in electronic form.", level: 1 },
      { q: "The market in which securities are sold for the first time is called the:", options: ["secondary market", "primary market", "money market", "stock exchange"], answer: 1, explain: "The primary (new issues) market is where new securities are first sold, so it directly helps capital formation.", level: 1 },
      { q: "The head office of SEBI is located in:", options: ["New Delhi", "Kolkata", "Mumbai", "Chennai"], answer: 2, explain: "SEBI was set up in 1988 and given statutory powers by the SEBI Act, 1992. Its head office is in Mumbai.", level: 1 },

      { q: "Which of the following pairs is correctly matched?", options: ["Call money: repayable on demand, 1 to 15 days", "Treasury bill: issued by commercial banks, 5 years", "Commercial paper: secured by government guarantee, 5 years", "Certificate of deposit: issued by RBI to the public, 10 years"], answer: 0, explain: "Call money is used for interbank borrowing and is repayable on demand with maturity of 1 to 15 days. The other pairs are wrong.", level: 2 },
      { q: "Tirupati Steels offers one new share for every four shares held to its existing shareholders at ₹120, while the market price is ₹150. The method of floatation used is:", options: ["Offer for sale", "Private placement", "e-IPO", "Rights issue"], answer: 3, explain: "New shares offered to existing shareholders in proportion to their holdings form a rights issue.", level: 2 },
      { q: "The Government needs funds for 91 days. The RBI issues an instrument on its behalf at ₹97.50 per ₹100 and it will be repaid at ₹100 on maturity. The instrument is a:", options: ["Commercial paper", "Treasury bill", "Call money", "Certificate of deposit"], answer: 1, explain: "A treasury bill is issued at a discount and repaid at par, with no interest, so it is a zero-coupon bond.", level: 2 },
      {
        q: "Assertion (A): A stock exchange provides liquidity to existing securities.\nReason (R): Investors can sell their securities on the exchange at any time and convert them into cash.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Liquidity means ease of converting securities to cash. The exchange gives a ready market for buying and selling, so R explains A.", level: 2, keepOrder: true
      },
      { q: "Which of the following is a feature of the primary market?", options: ["Securities that are already issued are bought and sold", "Prices are decided by demand and supply on a daily basis", "Securities are sold for the first time and funds flow directly to the company", "Only listed securities are traded"], answer: 2, explain: "In the primary market, new securities are sold by the company itself, so funds go directly to it. The other options describe the secondary market.", level: 2 },

      { q: "A director of Meghdoot Ltd bought a large number of shares just before the company's unpublished merger news was announced, and SEBI took action against him. This falls under which function of SEBI?", options: ["Regulatory function", "Protective function", "Developmental function", "Allocative function"], answer: 1, explain: "Insider trading is trading using unpublished price-sensitive information. Prohibiting it is a protective function of SEBI.", level: 3 },
      {
        q: "Assertion (A): Commercial paper can be issued by any small firm to raise short-term funds.\nReason (R): Commercial paper is an unsecured promissory note.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "A is false, because commercial paper is issued by large creditworthy companies. R is true, as no security backs it.", level: 3, keepOrder: true
      },
      { q: "Which statement about certificates of deposit (CDs) is correct?", options: ["They are secured long-term bonds issued by companies", "They are used only for interbank loans", "They are unsecured, negotiable, short-term instruments in bearer form issued by banks and financial institutions", "They are issued by the Government at a discount"], answer: 2, explain: "CDs are unsecured, negotiable and issued in bearer form by commercial banks and development financial institutions, especially when liquidity is tight.", level: 3 },
      { q: "Which statement correctly compares the capital market and the money market?", options: ["Money market instruments are riskier than capital market securities", "The capital market deals in funds of up to one year", "The money market usually needs a small outlay and the capital market a huge outlay", "Capital market securities carry higher risk and higher expected returns"], answer: 3, explain: "The capital market offers higher expected returns with more risk. The money market is safer with lower returns, usually involves huge outlays, and deals in funds up to one year.", level: 3 }
    ],
    written: [
      { q: "What is a financial market?", a: "A financial market is a market for the creation and exchange of financial assets. It links savers with investors.", marks: 1 },
      { q: "What is meant by dematerialisation?", a: "Dematerialisation is converting securities from paper certificates into electronic form, held in a demat account with a depository participant.", marks: 1 },
      { q: "Distinguish between the primary market and the secondary market on any two points.", a: "1. Securities: in the primary market they are sold for the first time; in the secondary market existing securities are bought and sold.\n2. Funds: in the primary market funds flow from savers to the company directly and help capital formation; in the secondary market the company does not get funds, but the market gives liquidity and marketability to the securities.", marks: 2 },
      { q: "Explain Treasury bill and Call money as money market instruments.", a: "1. Treasury bill: a short-term borrowing instrument of the Government of India, issued by the RBI on its behalf for less than a year. It is issued at a discount and repaid at par, so it is a zero-coupon bond.\n2. Call money: short-term finance repayable on demand, with a maturity of 1 to 15 days, used mainly for interbank transactions; the interest rate is called the call rate.", marks: 2 },
      { q: "Explain any three functions of a stock exchange.", a: "1. Providing liquidity and marketability to existing securities: investors can sell securities and get cash at any time.\n2. Pricing of securities: the interaction of demand and supply sets the price, which helps in price discovery.\n3. Safety of transactions: only listed securities are traded and the exchange has rules and regulations that protect investors. (Also: contributing to economic growth, spreading the equity cult, scope for healthy speculation.)", marks: 3 },
      { q: "Explain any three methods of floatation of new issues in the primary market.", a: "1. Offer through prospectus: the company invites the public to subscribe to its securities through a prospectus.\n2. Offer for sale: securities are first sold in bulk to intermediaries such as brokers, who then resell them to the public.\n3. Private placement: securities are allotted to institutional investors and selected individuals. (Also: rights issue and e-IPO.)", marks: 3 },
      { q: "Explain the protective functions of SEBI.", a: "1. It prohibits insider trading, i.e. dealing in securities using unpublished price-sensitive information.\n2. It prohibits fraudulent and unfair trade practices such as making misleading statements to induce sales, and price rigging.\n3. It undertakes investor education and awareness, so that investors know their rights and can protect themselves.", marks: 3 },
      { q: "Explain any five instruments of the money market.", a: "1. Treasury bill: a zero-coupon short-term government instrument issued by the RBI at a discount and repaid at par.\n2. Commercial paper: an unsecured, negotiable promissory note issued by large creditworthy companies for 15 days to one year, often for bridge financing.\n3. Call money: interbank short-term finance repayable on demand, with a maturity of 1 to 15 days.\n4. Certificate of deposit: an unsecured, negotiable instrument in bearer form issued by commercial banks and development financial institutions.\n5. Commercial bill: a bill of exchange used to finance the working capital needs of firms; a trade bill accepted by a bank becomes a commercial bill.", marks: 5 },
      { q: "Distinguish between the capital market and the money market on any five points.", a: "1. Participants: capital market has financial institutions, banks, companies, foreign investors and retail investors; money market has mainly RBI, banks, financial institutions and finance companies.\n2. Instruments: shares, debentures and bonds in the capital market; treasury bills, commercial paper, call money, certificates of deposit and commercial bills in the money market.\n3. Duration: medium and long term in the capital market; up to one year in the money market.\n4. Investment outlay: small amounts can be invested in the capital market; the money market usually needs huge amounts.\n5. Safety and return: capital market securities are riskier with higher expected returns; money market instruments are safer with lower returns.", marks: 5 },
      { q: "Case study: Sanjay Pharma Ltd has applied to raise funds from the public and wants to list on a stock exchange. At the same time, SEBI found that a broker had spread false rumours to push up the price of a company's shares. SEBI also cancelled the registration of a merchant banker and has begun conducting workshops for small investors on safe investing.\n(i) Name the market in which Sanjay Pharma will first sell its shares.\n(ii) Identify the practice of the broker.\n(iii) Classify the two functions of SEBI described at the end.", a: "(i) The primary market (new issues market), since the company is selling shares to the public for the first time.\n(ii) Price rigging, because the broker spread false rumours 'to push up the price of a company's shares'. SEBI prohibits it under its protective functions.\n(iii) Cancelling the registration of a merchant banker is a regulatory function (registering and regulating intermediaries). Conducting workshops for small investors is a protective (investor education) function, which also develops the market.", marks: 4, type: "case" }
    ]
  },
  "marketing": {
    mcq: [
      { q: "Which of the following is NOT one of the 4 Ps of the marketing mix?", options: ["Price", "Promotion", "Place", "Production"], answer: 3, explain: "The 4 Ps are Product, Price, Place and Promotion. Production is not a part of the marketing mix.", level: 1 },
      { q: "The philosophy that customers favour products that are widely available and low priced, so the focus is on mass production and lower cost, is the:", options: ["production concept", "product concept", "selling concept", "marketing concept"], answer: 0, explain: "The production concept focuses on availability and affordability, achieved through mass production and low cost.", level: 1 },
      { q: "A brand or a part of a brand that is given legal protection is called a:", options: ["brand mark", "brand name", "trademark", "label"], answer: 2, explain: "A trademark is a registered brand (or part of it) with exclusive legal protection. A brand mark is only the part that cannot be spoken.", level: 1 },
      { q: "Which of the following is NOT an element of the promotion mix?", options: ["Advertising", "Branding", "Public relations", "Personal selling"], answer: 1, explain: "The promotion mix has advertising, personal selling, sales promotion and public relations. Branding is part of the product element.", level: 1 },
      { q: "Which of the following is NOT a component of physical distribution?", options: ["Transportation", "Warehousing", "Inventory control", "Pricing"], answer: 3, explain: "Physical distribution consists of order processing, transportation, warehousing and inventory control. Pricing belongs to the price element.", level: 1 },

      { q: "A crate holding 24 cartons of soap is used for storing and moving the goods from the factory to the godown. This is:", options: ["primary packaging", "secondary packaging", "transportation packaging", "labelling"], answer: 2, explain: "Packaging used for storage and transport, such as corrugated boxes and crates, is transportation packaging.", level: 2 },
      { q: "Everest Dairy supplies milk packets to local retailers, who sell them to households. The channel of distribution is:", options: ["Zero level", "One level", "Two level", "Three level"], answer: 1, explain: "Manufacturer → retailer → consumer has one intermediary, so it is a one-level channel.", level: 2 },
      { q: "A pack of mustard oil prints the ingredients and net weight on its cover. Which function of labelling is this?", options: ["Grading the product", "Promoting the product", "Protecting the product", "Describing the product and its contents"], answer: 3, explain: "Information on contents, quantity and ingredients describes the product and its contents.", level: 2 },
      {
        q: "Assertion (A): Selling is only a part of marketing.\nReason (R): Marketing starts before production and continues after the sale, while selling mainly transfers ownership.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Marketing includes market research, product design, pricing, promotion and after-sales service, so selling is only one activity within it.", level: 2, keepOrder: true
      },
      { q: "Pratham Tyres announces 'buy three tyres and get the fourth free' for ten days. This is an example of:", options: ["advertising", "personal selling", "sales promotion", "public relations"], answer: 2, explain: "A short-term incentive to encourage immediate purchase is sales promotion.", level: 2 },

      { q: "Zenith Cameras keeps adding new features to its camera, believing customers always want the best quality, though most buyers want a simple camera at a low price. Which marketing philosophy is Zenith following?", options: ["Production concept", "Selling concept", "Marketing concept", "Product concept"], answer: 3, explain: "Focusing on better and better product features without studying the customer's actual need is the product concept.", level: 3 },
      {
        q: "Assertion (A): A brand name is the part of a brand that can be spoken.\nReason (R): A trademark is a brand that has no legal protection.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 2, explain: "A is true. R is false, because a trademark is a brand that has been given legal protection.", level: 3, keepOrder: true
      },
      { q: "Which of the following correctly describes a three-level channel of distribution?", options: ["Manufacturer → agent → wholesaler → retailer → consumer", "Manufacturer → retailer → consumer", "Manufacturer → consumer", "Manufacturer → wholesaler → retailer → consumer"], answer: 0, explain: "A three-level channel has three intermediaries: agent, wholesaler and retailer. The last option is a two-level channel.", keepOrder: true, level: 3 },
      { q: "The government fixes a ceiling price for certain essential medicines, so Medico Pharma cannot charge more than that. Which factor affecting price does this show?", options: ["Extent of competition", "Government and legal regulations", "Pricing objectives", "Product cost"], answer: 1, explain: "A price ceiling fixed by law is a government and legal regulation limiting the price a firm can charge.", level: 3 }
    ],
    written: [
      { q: "Define the marketing mix.", a: "The marketing mix is the set of marketing tools that a firm combines to reach its target market. It consists of the 4 Ps: product, price, place and promotion.", marks: 1 },
      { q: "What is meant by grading? Give one example.", a: "Grading is classifying products into groups on the basis of features such as size and quality. It is common for agricultural products, e.g. grading of wheat or apples.", marks: 1 },
      { q: "Distinguish between marketing and selling on any two points.", a: "1. Focus: marketing focuses on customer satisfaction; selling focuses on transferring ownership and the seller's needs.\n2. Scope: marketing starts before production and continues after sale; selling starts after production and ends with the sale.", marks: 2 },
      { q: "State any two functions of packaging.", a: "1. Protection: packaging protects the product from damage, spoilage and leakage.\n2. Identification and promotion: attractive packaging identifies the product and promotes it. (Also: facilitating use.)", marks: 2 },
      { q: "Explain any three functions of labelling.", a: "1. Describes the product and its contents, e.g. ingredients, weight, usage.\n2. Identifies the product or brand, helping buyers recognise it among similar items.\n3. Provides information required by law, such as statutory warnings. (Also: grading the product and helping in promotion.)", marks: 3 },
      { q: "Explain any three merits of advertising.", a: "1. Mass reach: it reaches a large number of people over a wide area at the same time.\n2. Builds customer confidence: buyers feel assured by well-advertised, branded products.\n3. Expressiveness and economy: art, sound and colour can present the message attractively, and the cost per person reached is low. (Also: it helps to introduce new products.)", marks: 3 },
      { q: "Distinguish the selling concept from the marketing concept with an example of each.", a: "1. Selling concept: customers will not buy enough unless persuaded, so the focus is on aggressive selling and promotion, e.g. a vendor pressing customers to buy goods they do not need.\n2. Marketing concept: the focus is on finding the needs of customers and satisfying them better than competitors, e.g. a firm that does market research before designing a product.\n3. Starting point and goal: the selling concept starts with the existing product and aims at sales volume; the marketing concept starts with the customer and aims at customer satisfaction and long-term profit.", marks: 3 },
      { q: "Explain the factors that affect the price of a product.", a: "1. Product cost: price must cover the cost (fixed, variable and semi-variable), with a margin of profit.\n2. Utility and demand: price depends on the utility buyers get and on the demand for the product.\n3. Extent of competition: where competition is high, prices are kept low.\n4. Government and legal regulations: the government may fix or regulate prices of essential goods.\n5. Pricing objectives: e.g. maximising profit, gaining market share or being a quality leader.\n6. Marketing methods used: distribution, advertising and other expenses affect the price.", marks: 5 },
      { q: "Explain the components of the promotion mix.", a: "1. Advertising: a paid, non-personal presentation of ideas, goods or services by an identified sponsor; it reaches many people.\n2. Personal selling: an oral presentation in conversation with prospective buyers to make sales; it is personal, two-way and flexible.\n3. Sales promotion: short-term incentives to encourage immediate purchase, e.g. rebates, discounts, refunds, product combinations, quantity gifts, lucky draws, contests, sampling.\n4. Public relations: managing communication to build a positive image of the firm, through press relations, product publicity, corporate communication, lobbying and counselling.\n5. A firm combines these four in a mix suited to its product, market and budget.", marks: 5 },
      { q: "Case study: Kesar Organics sells packaged turmeric. It sells in two ways: through its own website directly to buyers, and through local stores. Its pack carries a spice-leaf symbol and the words 'Kesar Gold', and the outer carton holds 10 packets. Kesar Organics buys turmeric from farmers who grade it into two sizes. To attract buyers it offers a free spoon with every pack for a month.\n(i) Identify the channel of distribution used in the first way.\n(ii) Name the brand name and the brand mark, and the level of packaging of the carton.\n(iii) Identify the marketing function related to the farmers' work and the promotion tool used in the last sentence.", a: "(i) Zero-level (direct) channel, since the company sells through 'its own website directly to buyers' with no intermediary. Selling through local stores is the one-level channel.\n(ii) Brand name: 'Kesar Gold' (can be spoken). Brand mark: the spice-leaf symbol (recognised but not spoken). The outer carton holding 10 packets is secondary packaging.\n(iii) The farmers who 'grade the turmeric into two sizes' perform the marketing function of grading. Offering 'a free spoon with every pack for a month' is a sales promotion (quantity gift).", marks: 4, type: "case" }
    ]
  },
  "consumer-protection": {
    mcq: [
      { q: "The authority set up under the Consumer Protection Act, 2019 to protect the rights of consumers as a class is the:", options: ["District Commission", "Securities and Exchange Board of India", "Central Consumer Protection Authority", "State Commission"], answer: 2, explain: "The Central Consumer Protection Authority (CCPA) acts against unfair trade practices and misleading advertisements affecting consumers as a class.", level: 1 },
      { q: "The right to be informed gives a consumer the right to get information about the:", options: ["quality, quantity, potency, purity, standard and price of goods", "profit earned by the seller", "names of the seller's suppliers", "salary of the shop employees"], answer: 0, explain: "A consumer must be given facts such as quality, quantity, potency, purity, standard and price so that he can make a wise choice.", level: 1 },
      { q: "The Hallmark is a quality mark used for:", options: ["agricultural products", "electrical goods", "processed fruit products", "gold and silver jewellery"], answer: 3, explain: "Hallmark certifies the purity of jewellery. ISI is for electrical and industrial goods, Agmark for agricultural products and FPO for processed fruit products.", level: 1 },
      { q: "An appeal against an order of a State Commission can be made to the:", options: ["District Commission", "National Commission", "High Court", "Central Consumer Protection Authority"], answer: 1, explain: "Appeals against a State Commission order lie with the National Commission, within 30 days.", level: 1 },
      { q: "Agmark certification is given to:", options: ["agricultural products", "electrical appliances", "medicines", "textiles"], answer: 0, explain: "Agmark is the quality certification for agricultural products such as grains, spices and oils.", level: 1 },

      { q: "Anita bought a hair dryer that overheated and burnt her hand. Which consumer right was violated?", options: ["Right to choose", "Right to safety", "Right to be heard", "Right to consumer education"], answer: 1, explain: "Goods hazardous to life and property violate the right to safety, which protects consumers against such goods and services.", level: 2 },
      { q: "In a remote village, the only shop sells just one brand of salt at a high price, so villagers have no alternative. Which right is affected?", options: ["Right to safety", "Right to be informed", "Right to be heard", "Right to choose"], answer: 3, explain: "The right to choose means access to a variety of goods at competitive prices. The villagers have no choice.", level: 2 },
      {
        q: "Assertion (A): A complaint about services worth ₹1.5 crore should be filed before the State Commission.\nReason (R): The State Commission handles complaints where the consideration paid is above ₹50 lakh and up to ₹2 crore.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "₹1.5 crore lies between ₹50 lakh and ₹2 crore, and that is exactly the State Commission's jurisdiction under the 2021 rules.", level: 2, keepOrder: true
      },
      { q: "Suresh paid ₹30 lakh for a flat and has a complaint against the builder for defective services. Where should he file the complaint?", options: ["District Commission", "State Commission", "National Commission", "Supreme Court"], answer: 0, explain: "Up to ₹50 lakh is within the jurisdiction of the District Commission, the lowest tier.", level: 2 },
      { q: "Bhavna paid ₹6,000 online for a branded watch from a seller on an e-commerce app, but received a fake one. Her position is that:", options: ["she cannot complain, since online purchases are not covered", "she cannot complain because she did not visit the shop", "she can complain, since the 2019 Act covers online and e-commerce transactions", "she can complain only to the Supreme Court"], answer: 2, explain: "The Consumer Protection Act, 2019 covers both offline and online transactions, including e-commerce.", level: 2 },

      { q: "Which sequence of appeal periods under the Consumer Protection Act, 2019 is correct?", options: ["District to State: 30 days; State to National: 45 days; National to Supreme Court: 60 days", "District to State: 45 days; State to National: 30 days; National to Supreme Court: 30 days", "District to State: 45 days; State to National: 45 days; National to Supreme Court: 30 days", "District to State: 30 days; State to National: 30 days; National to Supreme Court: 45 days"], answer: 1, explain: "Appeals go from the District Commission to the State Commission within 45 days, and the next two appeals within 30 days each.", level: 3 },
      {
        q: "Assertion (A): A complaint can be filed only by the consumer himself.\nReason (R): A registered voluntary consumer association, the government, the CCPA and the legal heir of a deceased consumer can also file a complaint.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "A is false because many others can file on a consumer's behalf. R is true and contradicts A.", level: 3, keepOrder: true
      },
      { q: "Four complaints involve consideration paid of: ₹40 lakh, ₹1.2 crore, ₹3 crore and ₹60 lakh. Which two go to the State Commission?", options: ["₹1.2 crore and ₹60 lakh", "₹40 lakh and ₹60 lakh", "₹1.2 crore and ₹3 crore", "₹3 crore only"], answer: 0, explain: "The State Commission takes cases above ₹50 lakh and up to ₹2 crore: ₹60 lakh and ₹1.2 crore. ₹40 lakh goes to the District Commission and ₹3 crore to the National Commission.", level: 3 },
      { q: "Nirmal bought ten sewing machines for resale in his shop. One was defective and he filed a complaint as a consumer. His complaint is likely to fail because:", options: ["a complaint must be filed within a week", "he did not pay in cash", "he bought the goods for resale, so he is not a consumer under the Act", "sewing machines are not covered by the Act"], answer: 2, explain: "A person who obtains goods for resale or a commercial purpose is not a consumer under the Act.", level: 3 }
    ],
    written: [
      { q: "What is the Central Consumer Protection Authority (CCPA)?", a: "The CCPA is the body set up under the Consumer Protection Act, 2019 to protect, promote and enforce the rights of consumers as a class, and to act against unfair trade practices and misleading advertisements.", marks: 1 },
      { q: "Name the quality mark used on (a) electrical goods and (b) processed fruit products.", a: "(a) ISI mark on electrical and industrial goods; (b) FPO mark on processed fruit products.", marks: 1 },
      { q: "State any two responsibilities of consumers.", a: "1. Read labels carefully and follow the manufacturer's instructions; buy only standardised goods with marks such as ISI, Agmark and Hallmark.\n2. Ask for a cash memo and file a complaint in case of any shortcoming. (Also: be honest, be assertive, respect the environment.)", marks: 2 },
      { q: "State any two reliefs that a consumer commission can grant to a consumer.", a: "1. Remove the defect in the goods or replace them with defect-free goods, or refund the price paid.\n2. Pay compensation for loss or injury suffered by the consumer. (Also: punitive damages, withdrawal of hazardous goods, corrective advertisements, discontinuing the unfair trade practice.)", marks: 2 },
      { q: "Explain any three points of importance of consumer protection from the point of view of business.", a: "1. Long-term interest of business: satisfied customers return and bring new customers, which helps long-run profit.\n2. Social responsibility: business uses society's resources and so has a duty to serve consumers fairly.\n3. Moral justification: it is the moral duty of a business to protect consumers from exploitation such as adulteration. (Also: avoiding government intervention.)", marks: 3 },
      { q: "Who can file a complaint under the Consumer Protection Act, 2019? Mention any three.", a: "1. A consumer to whom the goods were sold or the service provided.\n2. Any registered voluntary consumer association, or the Central or State Government or the CCPA.\n3. One or more consumers on behalf of many having the same interest, the legal heir of a deceased consumer, or the parent or guardian of a minor consumer.", marks: 3 },
      { q: "Explain the role of consumer organisations and NGOs in protecting consumers.", a: "1. They educate consumers about their rights through campaigns, periodicals and awareness programmes.\n2. They test products in laboratories and publish the results, so consumers know about quality.\n3. They provide legal assistance, file complaints in consumer commissions and take up cases on behalf of consumers, and encourage protests against exploitation.", marks: 3 },
      { q: "Explain any five rights of consumers.", a: "1. Right to safety: protection against goods and services hazardous to life and property, e.g. buying electrical goods with the ISI mark.\n2. Right to be informed: about the quality, quantity, potency, purity, standard and price of goods.\n3. Right to choose: access to a variety of goods at competitive prices.\n4. Right to be heard: to file a complaint and be assured that consumer interests will be considered at appropriate forums.\n5. Right to seek redressal: relief such as replacement, repair or compensation against unfair trade practices.\n6. Right to consumer education: to acquire the knowledge needed to be a well-informed consumer.", marks: 5 },
      { q: "Explain the three-tier consumer redressal machinery under the Consumer Protection Act, 2019, with the pecuniary limits and the appeal provisions.", a: "1. District Commission: the lowest tier, set up in each district; it hears complaints where the consideration paid is up to ₹50 lakh.\n2. State Commission: set up in each state; it hears complaints above ₹50 lakh and up to ₹2 crore.\n3. National Commission: the top tier; it hears complaints where the value is above ₹2 crore.\n4. Appeals: against a District Commission order to the State Commission within 45 days; against a State Commission order to the National Commission within 30 days.\n5. Against a National Commission order, appeal lies to the Supreme Court within 30 days.\n(The limits above follow the 2021 rules; the Act originally fixed ₹1 crore and ₹10 crore.)", marks: 5 },
      { q: "Case study: Reena paid ₹8 lakh for a car from Sunrise Motors, which advertised it as 'fully tested and safe'. Within a week the brakes failed and she was injured. The company refused to repair or replace it. Reena has the dealer's bill. A voluntary consumer association has offered to help her.\n(i) Which consumer rights were violated?\n(ii) Where should Reena file her complaint, and why?\n(iii) Name two reliefs she can ask for.", a: "(i) Right to safety, because the car was hazardous and the brakes failed ('fully tested and safe' was untrue); also right to be informed, since the advertisement gave misleading information; and right to seek redressal, since the company 'refused to repair or replace it'.\n(ii) The District Commission, because the consideration paid (₹8 lakh) is within its limit of ₹50 lakh. She has the dealer's bill as proof, and the voluntary consumer association can also file or help.\n(iii) Replacement of the car with a defect-free one or refund of the price, and compensation for the injury suffered. (Also: punitive damages, corrective advertisement.)", marks: 4, type: "case" }
    ]
  }
});
